chapter(11, 'Checklists and handover', 'Complete the housekeeping shift checklist, submit it, and write the handover note for the next shift.',
        'Neha (Supervisor)', 'supervisor', menu='Housekeeping & Maintenance > Checklists & handover')
step('Neha is at the end of the morning shift. On Modules Home she opens the Housekeeping & Maintenance module.', 'A shift is not over until its checklist is done and its handover is written.', target='sel:.fit-home-grid',
     auto=['key:Escape', 'user:supervisor'], action='read', expect='Modules Home for Neha.', check="ctx.uid==='supervisor'")
tile('Housekeeping & Maintenance', 'Click the Housekeeping & Maintenance tile.', 'The checklists are the third tile.', expect='The module page opens.')
leaf('Housekeeping & Maintenance', 'Checklists', 'Click the Checklists & handover tile.', 'It keeps the checklists of the current shift and the notes between shifts.', expect='The page opens on My checklists.', check="ctx.page==='handover'")
read('My checklists shows the current shift, Morning 07:00 to 15:00, and two checklists: 1. Housekeeping floor check and 2. Maintenance rounds, each with its percentage done.', 'The percentage tells the manager how far the shift has got.', target='btn:1. Housekeeping floor check', expect='Two checklists for the morning shift.')
step('Tick each item of the Housekeeping floor check: the trolley is stocked, corridors are clean, found items are logged, the Do-Not-Disturb rooms are noted, linen is checked, repairs are reported and chemicals are locked.', 'Each tick is a statement that the thing was really checked.', target='btn:Submit checklist',
     auto=['click:btn:Trolley stocked', 'click:btn:Corridors floors', 'click:modalbtn:Simulate photo', 'click:modalbtn:Save & tick', 'click:btn:Lost & found items logged', 'click:btn:Note Do-Not-Disturb', 'click:btn:Linen par levels', 'click:btn:Repairs reported', 'click:btn:Chemicals locked'], action='click', expect='All seven items are ticked, the corridor item carries a simulated photo, and the checklist shows 100 per cent.')
click('btn:Submit checklist', 'Click Submit checklist.', 'A submitted checklist cannot be changed and is visible to the manager.', expect='The checklist is submitted.')
click('tab:Handover', 'Open the Handover tab.', 'Handover notes are what one shift tells the next: open issues, keys and guest notes.', expect='The handover notes are listed.')
click('btn:Write handover note', 'Click Write handover note.', 'The outgoing supervisor writes it before leaving.', expect='The Write handover note dialog opens.', check="has('Submit handover')")
step('Choose the desk Housekeeping and the outgoing shift Morning. Untick Nothing to report and type the open issue: Room 107 air conditioner repaired, check it at the inspection.', 'A note that says nothing to report is also a statement, so it is a tick box.', target='field:Open issues',
     auto=['uncheck:field:Nothing to report', 'type:field:Open issues|Room 107 air conditioner repaired, check it at the inspection'], action='type', expect='The open issue is typed.')
click('modalbtn:Submit handover', 'Click Submit handover.', 'The next shift sees the note when it opens the screen and marks it done.', expect='The handover is saved.')
read('The Housekeeping handover of the morning shift is now at the top of the list, with Mark done for the evening shift to click after reading it. The filters All, Housekeeping and Maintenance narrow the list.', 'Reading and marking done closes the loop between shifts.', target='btn:Mark done', expect='The handover list with the new note.')
